import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        present = [False] * (N + 1)
        total_steps = 0

        for i in range(1, N + 1):
            parent = A[i - 1]

            if parent == 0:
                left_count = 0
                right_count = sum(present[j] for j in range(1, i))
                total_steps += min(left_count, right_count)
            else:
                left_count = 0
                current = parent
                while current != 0:
                    if present[current]:
                        left_count += 1
                    current -= 1

                right_count = 0
                current = parent
                while current < i:
                    if present[current]:
                        right_count += 1
                    current += 1

                total_steps += min(left_count, right_count)

            present[i] = True

        results.append(str(total_steps))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
